@@ -0,0 +1,141 @@
+<!DOCTYPE html>
+<html lang="en">
+<head>
+    <meta charset="UTF-8">
+    <meta name="viewport" content="width=device-width, initial-scale=1.0">
+    <title>Scientific Calculator</title>
+    <style>
+        body {
+            display: flex;
+            justify-content: center;
+            align-items: center;
+            min-height: 100vh;
+            margin: 0;
+            padding: 20px;
+            background: #090d16;
+        }
+        .calculator {
+            background: rgba(16, 24, 40, 0.75);
+            backdrop-filter: blur(20px);
+            padding: 24px;
+            border-radius: 12px;
+            box-shadow: 0 0 30px rgba(56, 189, 248, 0.4);
+        }
+        .display {
+            font-size: 24px;
+            font-family: 'Inter', sans-serif;
+            padding: 12px;
+            border: none;
+            border-radius: 6px;
+            background: #1a1d23;
+            color: #fff;
+        }
+        .keypad {
+            display: grid;
+            grid-template-columns: repeat(4, 1fr);
+            gap: 10px;
+        }
+        .key {
+            padding: 12px;
+            border: none;
+            border-radius: 6px;
+            background: #1a1d23;
+            color: #fff;
+            cursor: pointer;
+        }
+        .key:hover {
+            background: #2a2d33;
+        }
+    </style>
+</head>
+<body>
+    <div class="calculator">
+        <input type="text" id="display" class="display" value="0" disabled>
+        <div class="keypad">
+            <button class="key" id="clear">C</button>
+            <button class="key" id="backspace">DEL</button>
+            <button class="key" id="sin">sin</button>
+            <button class="key" id="cos">cos</button>
+            <button class="key" id="tan">tan</button>
+            <button class="key" id="sqrt">√</button>
+            <button class="key" id="power">^</button>
+            <button class="key" id="divide">/</button>
+            <button class="key" id="multiply">*</button>
+            <button class="key" id="subtract">-</button>
+            <button class="key" id="add">+</button>
+            <button class="key" id="equals">=</button>
+            <button class="key" id="0">0</button>
+            <button class="key" id="1">1</button>
+            <button class="key" id="2">2</button>
+            <button class="key" id="3">3</button>
+            <button class="key" id="4">4</button>
+            <button class="key" id="5">5</button>
+            <button class="key" id="6">6</button>
+            <button class="key" id="7">7</button>
+            <button class="key" id="8">8</button>
+            <button class="key" id="9">9</button>
+            <button class="key" id=".">.</button>
+        </div>
+    </div>
+    <script>
+        const display = document.getElementById('display');
+        const keys = document.querySelectorAll('.key');
+        let currentExpression = '';
+        let history = [];
+        
+        keys.forEach(key => {
+            key.addEventListener('click', () => {
+                const keyValue = key.id;
+                switch (keyValue) {
+                    case 'clear':
+                        currentExpression = '';
+                        display.value = '0';
+                        break;
+                    case 'backspace':
+                        currentExpression = currentExpression.slice(0, -1);
+                        display.value = currentExpression || '0';
+                        break;
+                    case 'sin':
+                    case 'cos':
+                    case 'tan':
+                    case 'sqrt':
+                    case 'power':
+                        currentExpression += keyValue + '(';
+                        display.value = currentExpression;
+                        break;
+                    case 'equals':
+                        try {
+                            const result = eval(currentExpression);
+                            display.value = result;
+                            history.push(currentExpression + ' = ' + result);
+                            currentExpression = result.toString();
+                        } catch (error) {
+                            display.value = 'Error';
+                        }
+                        break;
+                    default:
+                        currentExpression += keyValue;
+                        display.value = currentExpression;
+                }
+            });
+        });
+        
+        // Send calculation to backend API
+        const calculate = async (expression) => {
+            try {
+                const response = await fetch('/api/calculate', {
+                    method: 'POST',
+                    headers: {
+                        'Content-Type': 'application/json'
+                    },
+                    body: JSON.stringify({ expression })
+                });
+                const result = await response.json();
+                return result.result;
+            } catch (error) {
+                console.error(error);
+            }
+        };
+    </script>
+</body>
+</html>
